from pathlib import Path
import base64, hashlib, subprocess, zlib

ROOT = Path(__file__).resolve().parent
ENGINE = ROOT / "app/src/main/java/com/a340/technicalassistant/LineAssistantEngine.kt"
GRADLE = ROOT / "app/build.gradle.kts"

def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

expected_before = {
    ENGINE: "a4114243f4a2f25f1a0e1420f5e052cc58a348dfeda2cac763a4ef8a8ac775d6",
    GRADLE: "25214c75359391c7e022f6d12cfe3434d31eff61a83a352502fd0aad003e7945",
}
for path, expected in expected_before.items():
    actual = sha(path)
    if actual != expected:
        raise SystemExit(f"PC5 refuses non-PC4 runtime {path}: {actual} != {expected}")

PAYLOAD = ""
patch = zlib.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(patch).hexdigest() != "6fd6f13dafa5283a3a597204de5230747a0ef4b435c9409af670e8bc4755df9b":
    raise SystemExit("PC5 runtime patch SHA mismatch")

subprocess.run(["git", "apply", "--check", "-"], cwd=ROOT, input=patch, check=True)
subprocess.run(["git", "apply", "-"], cwd=ROOT, input=patch, check=True)

expected_after = {
    ENGINE: "d9d66b5a92663a357075fe17769cd57664d1a3f2bb6fab7f5003c4ccd3442d0f",
    GRADLE: "e8f93eb328d4788dfdb531851f3a5287aefcb86f824edc65ef0221de40239361",
}
for path, expected in expected_after.items():
    actual = sha(path)
    if actual != expected:
        raise SystemExit(f"PC5 output hash mismatch {path}: {actual} != {expected}")

print("Line Assistant 1.4.5-PC5 complete TSM branch source patch applied")
